{"policy_source":"from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, int(capacity_bytes))
        self.used_bytes = 0
        self.probation = OrderedDict()
        self.protected = OrderedDict()
        self.entries = {}
        self.history = {}
        self.ticks = 0

    def _remember(self, key):
        self.history[key] = min(255, self.history.get(key, 0) + 1)
        if len(self.history) > 8192:
            oldest = next(iter(self.history))
            del self.history[oldest]

    def _age(self):
        if self.ticks % 512 != 0:
            return
        for record in self.entries.values():
            record[1] = max(1, (record[1] + 1) // 2)
        for key in list(self.history):
            value = max(1, (self.history[key] + 1) // 2)
            if value == 1 and key not in self.entries:
                del self.history[key]
            else:
                self.history[key] = value

    def _protected_target(self):
        return max(1, (self.capacity_bytes * 3) // 5)

    def _demote(self):
        protected_bytes = sum(self.entries[key][0] for key in self.protected)
        while self.protected and protected_bytes > self._protected_target():
            key, _ = self.protected.popitem(last=False)
            self.probation[key] = None
            protected_bytes -= self.entries[key][0]

    def _victim(self):
        if self.probation:
            key = next(iter(self.probation))
            return key, False
        if self.protected:
            key = next(iter(self.protected))
            return key, True
        return None, False

    def access(self, key: int, size: int, now: int) -> list[int]:
        self.ticks += 1
        self._remember(key)
        self._age()

        if key in self.protected:
            record = self.entries[key]
            record[1] = min(255, record[1] + 1)
            self.protected.move_to_end(key)
            return []

        if key in self.probation:
            record = self.entries[key]
            record[1] = min(255, record[1] + 1)
            self.probation.pop(key)
            self.protected[key] = None
            self._demote()
            return []

        size = max(0, int(size))
        if self.capacity_bytes == 0 or size > self.capacity_bytes:
            return []

        candidate_frequency = max(1, self.history.get(key, 1))
        required = self.used_bytes + size - self.capacity_bytes
        victims = []
        simulated = set()
        remaining = required

        while remaining > 0:
            victim, is_protected = self._victim()
            if victim is None or victim in simulated:
                break
            simulated.add(victim)
            victim_size, victim_frequency = self.entries[victim][0], self.entries[victim][1]
            victims.append((victim, is_protected))
            remaining -= victim_size

            if is_protected and candidate_frequency <= victim_frequency:
                candidate_value = candidate_frequency / max(1, size)
                victim_value = victim_frequency / max(1, victim_size)
                if candidate_value <= victim_value:
                    return []

        if remaining > 0:
            return []

        evicted = []
        for victim, _ in victims:
            if victim in self.probation:
                self.probation.pop(victim)
            elif victim in self.protected:
                self.protected.pop(victim)
            record = self.entries.pop(victim)
            self.used_bytes -= record[0]
            evicted.append(victim)

        self.entries[key] = [size, candidate_frequency]
        self.probation[key] = None
        self.used_bytes += size
        self._demote()
        return evicted
